<script setup lang="ts">
useHead({title:'محصولات'});const route=useRoute(),{api}=useShopApi();const min=ref(String(route.query.min_price||'')),max=ref(String(route.query.max_price||'')),selected=reactive<Record<string,string>>({});const query=computed(()=>({search:route.query.search,category:route.query.category,brand:route.query.brand,available:route.query.available,min_price:route.query.min_price,max_price:route.query.max_price,sort:route.query.sort,attributes:Object.keys(selected).length?selected:undefined,per_page:24}));const[{data},{data:filters}]=await Promise.all([useAsyncData('catalog-products',()=>api<any>('/catalog/products',{query:query.value}),{watch:[query]}),useAsyncData('catalog-filters',()=>api<any>('/catalog/filters'))]);function setQuery(key:string,value:any){navigateTo({query:{...route.query,[key]:value||undefined}})}function price(){navigateTo({query:{...route.query,min_price:min.value||undefined,max_price:max.value||undefined}})}function attribute(slug:string,value:string){if(selected[slug]===value)delete selected[slug];else selected[slug]=value}
</script>
<template><div class="mx-auto max-w-7xl px-4 py-8"><div class="mb-7"><p class="text-sm text-slate-400">خانه / فروشگاه</p><h1 class="mt-2 text-2xl font-black">محصولات دست‌ساز</h1></div><div class="grid gap-7 lg:grid-cols-[250px_1fr]"><aside class="h-fit space-y-5 rounded-2xl border bg-white p-5"><p class="font-black">فیلترها</p><label class="flex items-center justify-between text-sm"><span>فقط کالاهای موجود</span><input type="checkbox" :checked="route.query.available==='1'" class="size-4 accent-brand-700" @change="setQuery('available',($event.target as HTMLInputElement).checked?'1':'')"></label><div class="border-t pt-5"><p class="text-sm font-bold">بازه قیمت (تومان)</p><div class="mt-3 grid grid-cols-2 gap-2"><input v-model="min" type="number" min="0" placeholder="از" class="h-10 min-w-0 rounded-lg border px-2"><input v-model="max" type="number" min="0" placeholder="تا" class="h-10 min-w-0 rounded-lg border px-2"></div><button class="mt-2 w-full rounded-lg bg-slate-100 py-2 text-xs font-bold" @click="price">اعمال قیمت</button></div><div class="border-t pt-5"><p class="text-sm font-bold">برند</p><div class="mt-3 max-h-48 space-y-2 overflow-auto"><label v-for="b in filters?.brands" :key="b.id" class="flex cursor-pointer items-center gap-2 text-sm text-slate-600"><input type="radio" name="brand" :checked="route.query.brand===b.slug" class="accent-brand-700" @change="setQuery('brand',b.slug)">{{b.title}}</label><button v-if="route.query.brand" class="text-xs text-rose-600" @click="setQuery('brand','')">حذف فیلتر برند</button></div></div><div v-for="a in filters?.attributes" :key="a.id" class="border-t pt-5"><p class="text-sm font-bold">{{a.title}}</p><div class="mt-3 flex flex-wrap gap-2"><button v-for="v in a.values" :key="v.id" :class="['rounded-lg border px-3 py-2 text-xs font-bold',selected[a.slug]===v.value?'border-brand-600 bg-brand-50 text-brand-700':'bg-white text-slate-600']" @click="attribute(a.slug,v.value)"><span v-if="v.color" class="ml-1 inline-block size-3 rounded-full align-middle" :style="{backgroundColor:v.color}"/>{{v.label}}</button></div></div></aside><main><div class="mb-4 flex items-center justify-between"><p class="text-sm text-slate-500">{{data?.total||0}} محصول</p><select :value="route.query.sort||''" class="rounded-xl border bg-white px-3 py-2 text-sm" @change="setQuery('sort',($event.target as HTMLSelectElement).value)"><option value="">جدیدترین</option><option value="popular">محبوب‌ترین</option><option value="price_asc">ارزان‌ترین</option><option value="price_desc">گران‌ترین</option></select></div><div v-if="data?.data?.length" class="grid grid-cols-2 gap-4 md:grid-cols-3 xl:grid-cols-4"><ProductCard v-for="p in data.data" :key="p.id" :product="p"/></div><div v-else class="rounded-2xl border border-dashed bg-white p-16 text-center"><p class="font-black">محصولی پیدا نشد</p><p class="mt-2 text-sm text-slate-400">فیلترها یا عبارت جستجو را تغییر دهید.</p></div></main></div></div></template>
